SELECT     TRUNC(SYSDATE)                                        AS report_date,      im.DEPT                                               AS dept_no,     d.DEPT_NAME                                           AS dept_name,     im.CLASS                                              AS class_no,     c.CLASS_NAME                                          AS class_name,     im.SUBCLASS                                           AS subclass_no,     sc.SUB_NAME                                           AS subclass_name,      im.ITEM                                               AS item_id,     im.ITEM_DESC                                          AS item_description,     im.STANDARD_UOM                                       AS uom,     im.PACK_IND                                           AS pack_ind,     im.STATUS                                             AS item_status,      isc.SUPPLIER                                          AS supplier_id,     sp.SUP_NAME                                           AS supplier_name,     sp.SUP_STATUS                                         AS supplier_status,     isc.PRIMARY_SUPP_IND                                  AS primary_supp_ind,     isc.PRIMARY_COUNTRY_IND                               AS primary_country_ind,      iscl.LOC                                              AS location_id,     il.LOC_TYPE                                           AS loc_type,     CASE il.LOC_TYPE         WHEN 'S' THEN 'Store'         WHEN 'W' THEN 'Warehouse'     END                                                   AS loc_type_desc,     CASE il.LOC_TYPE         WHEN 'S' THEN st.STORE_NAME         WHEN 'W' THEN wh.WH_NAME     END                                                   AS location_name,     il.STATUS                                             AS item_loc_status,      ril.REPL_METHOD                                       AS repl_method,     CASE ril.REPL_METHOD         WHEN 'C'  THEN 'Constant'         WHEN 'D'  THEN 'Dynamic'         WHEN 'F'  THEN 'Floating Point'         WHEN 'M'  THEN 'Min/Max'         WHEN 'T'  THEN 'Time Supply'         WHEN 'SO' THEN 'Store Orders'         ELSE ril.REPL_METHOD     END                                                   AS repl_method_desc,     ril.STOCK_CAT                                         AS stock_category,     CASE ril.STOCK_CAT         WHEN 'C' THEN 'Cross-Docked'         WHEN 'D' THEN 'Direct to Store'         WHEN 'L' THEN 'WH/Cross Link'         WHEN 'W' THEN 'Warehouse Stocked'         WHEN 'X' THEN 'PO Cross-link'     END                                                   AS stock_category_desc,      isc.UNIT_COST                                         AS isc_unit_cost,     iscl.UNIT_COST                                        AS iscl_unit_cost,     ROUND(NVL(iscl.UNIT_COST, 0) - NVL(isc.UNIT_COST, 0), 4)                                                           AS unit_cost_variance,     CASE         WHEN NVL(iscl.UNIT_COST, -1) != NVL(isc.UNIT_COST, -1)         THEN 'DIFFER'         ELSE 'MATCH'     END                                                   AS unit_cost_status,      isc.PICKUP_LEAD_TIME                                  AS isc_pickup_lead_time,     iscl.PICKUP_LEAD_TIME                                 AS iscl_pickup_lead_time,     NVL(iscl.PICKUP_LEAD_TIME, 0) - NVL(isc.PICKUP_LEAD_TIME, 0)                                                           AS pickup_lt_variance,     CASE         WHEN NVL(iscl.PICKUP_LEAD_TIME, -1) != NVL(isc.PICKUP_LEAD_TIME, -1)         THEN 'DIFFER'         ELSE 'MATCH'     END                                                   AS pickup_lt_status,      isc.ORIGIN_COUNTRY_ID                                 AS isc_origin_country,     iscl.ORIGIN_COUNTRY_ID                                AS iscl_origin_country,     CASE         WHEN NVL(iscl.ORIGIN_COUNTRY_ID, 'X') != NVL(isc.ORIGIN_COUNTRY_ID, 'X')         THEN 'DIFFER'         ELSE 'MATCH'     END                                                   AS origin_country_status,      isc.SUPP_PACK_SIZE                                    AS isc_supp_pack_size,     isc.INNER_PACK_SIZE                                   AS isc_inner_pack_size,     isc.LEAD_TIME                                         AS isc_lead_time,     isc.TI                                                AS isc_ti,     isc.HI                                                AS isc_hi,      NVL(iscl.UNIT_COST,        isc.UNIT_COST)             AS effective_unit_cost,     NVL(iscl.PICKUP_LEAD_TIME, isc.PICKUP_LEAD_TIME)      AS effective_pickup_lt,     NVL(iscl.ORIGIN_COUNTRY_ID,isc.ORIGIN_COUNTRY_ID)    AS effective_origin_country,      isc.LEAD_TIME                                         AS effective_lead_time,     isc.SUPP_PACK_SIZE                                    AS effective_supp_pack_size,     isc.TI                                                AS effective_ti,     isc.HI                                                AS effective_hi,      NVL(isc.TI, 0) * NVL(isc.HI, 0)         * NVL(isc.SUPP_PACK_SIZE, 1)                      AS isc_pallet_multiple,      (CASE WHEN NVL(iscl.UNIT_COST,-1)          != NVL(isc.UNIT_COST,-1)           THEN 1 ELSE 0 END      + CASE WHEN NVL(iscl.PICKUP_LEAD_TIME,-1) != NVL(isc.PICKUP_LEAD_TIME,-1)              THEN 1 ELSE 0 END      + CASE WHEN NVL(iscl.ORIGIN_COUNTRY_ID,'X') != NVL(isc.ORIGIN_COUNTRY_ID,'X')              THEN 1 ELSE 0 END     )                                                     AS total_diff_count,      CASE         WHEN NVL(iscl.UNIT_COST,-1) != NVL(isc.UNIT_COST,-1)              AND NVL(iscl.PICKUP_LEAD_TIME,-1) != NVL(isc.PICKUP_LEAD_TIME,-1)         THEN 'COST AND LEAD TIME - HIGH IMPACT'         WHEN NVL(iscl.UNIT_COST,-1) != NVL(isc.UNIT_COST,-1)         THEN 'COST ONLY - FINANCIAL IMPACT'         WHEN NVL(iscl.PICKUP_LEAD_TIME,-1) != NVL(isc.PICKUP_LEAD_TIME,-1)         THEN 'PICKUP LEAD TIME - ROQ TIMING IMPACT'         WHEN NVL(iscl.ORIGIN_COUNTRY_ID,'X') != NVL(isc.ORIGIN_COUNTRY_ID,'X')         THEN 'ORIGIN COUNTRY - IMPORT COST IMPACT'         ELSE 'OTHER PARAMETER DIFFERENCE'     END                                                   AS impact_classification,      CASE         WHEN NVL(iscl.UNIT_COST,-1) != NVL(isc.UNIT_COST,-1)         THEN 'Verify if location cost is intentional; if not, remove ISCL cost override'         WHEN NVL(iscl.PICKUP_LEAD_TIME,-1) != NVL(isc.PICKUP_LEAD_TIME,-1)         THEN 'Verify if location pickup LT reflects actual supplier performance; update if stale'         WHEN NVL(iscl.ORIGIN_COUNTRY_ID,'X') != NVL(isc.ORIGIN_COUNTRY_ID,'X')         THEN 'Verify origin country with trade compliance; update or remove ISCL override'         ELSE 'Review ISCL override values against ISC baseline and correct where stale'     END                                                   AS recommended_action,      iscl.CREATE_DATETIME                                  AS iscl_create_datetime,     iscl.LAST_UPDATE_DATETIME                             AS iscl_last_update,      ils.STOCK_ON_HAND                                     AS current_soh,     ils.AV_COST                                           AS weighted_avg_cost  FROM     MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY_LOC      iscl      JOIN  MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY    isc   ON  iscl.ITEM         = isc.ITEM                                                       AND iscl.SUPPLIER     = isc.SUPPLIER                                                       AND isc.PRIMARY_SUPP_IND    = 'Y'                                                       AND isc.PRIMARY_COUNTRY_IND = 'Y'      JOIN  MFCS_RDS.RDS_WV_REPL_ITEM_LOC        ril   ON  iscl.ITEM         = ril.ITEM                                                       AND iscl.LOC          = ril.LOCATION                                                       AND iscl.SUPPLIER     = ril.PRIMARY_REPL_SUPPLIER                                                       AND ril.REPL_METHOD  IS NOT NULL      JOIN  MFCS_RDS.RDS_WV_ITEM_LOC              il   ON  ril.ITEM          = il.ITEM                                                       AND ril.LOCATION      = il.LOC                                                       AND ril.LOC_TYPE      = il.LOC_TYPE      JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER           im   ON  iscl.ITEM         = im.ITEM                                                       AND im.TRAN_LEVEL     = im.ITEM_LEVEL     JOIN  MFCS_RDS.RDS_WV_DEPS                  d    ON  im.DEPT           = d.DEPT     JOIN  MFCS_RDS.RDS_WV_CLASS                 c    ON  im.DEPT           = c.DEPT                                                       AND im.CLASS          = c.CLASS     JOIN  MFCS_RDS.RDS_WV_SUBCLASS              sc   ON  im.DEPT           = sc.DEPT                                                       AND im.CLASS          = sc.CLASS                                                       AND im.SUBCLASS       = sc.SUBCLASS      LEFT JOIN MFCS_RDS.RDS_WV_STORE             st   ON  iscl.LOC          = st.STORE                                                       AND il.LOC_TYPE       = 'S'     LEFT JOIN MFCS_RDS.RDS_WV_WH               wh    ON  iscl.LOC          = wh.WH                                                       AND il.LOC_TYPE       = 'W'      LEFT JOIN MFCS_RDS.RDS_WV_SUPS              sp   ON  iscl.SUPPLIER     = sp.SUPPLIER      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH     ils   ON  iscl.ITEM         = ils.ITEM                                                       AND iscl.LOC          = ils.LOC                                                       AND ils.LOC_TYPE      = il.LOC_TYPE  WHERE     ril.REPL_METHOD  IS NOT NULL     AND il.STATUS    IN ('A','C')     AND im.STATUS     = 'A'     AND (         NVL(iscl.UNIT_COST,-1)          != NVL(isc.UNIT_COST,-1)         OR NVL(iscl.PICKUP_LEAD_TIME,-1) != NVL(isc.PICKUP_LEAD_TIME,-1)         OR NVL(iscl.ORIGIN_COUNTRY_ID,'X') != NVL(isc.ORIGIN_COUNTRY_ID,'X')     )  ORDER BY     (CASE WHEN NVL(iscl.UNIT_COST,-1) != NVL(isc.UNIT_COST,-1)           THEN 1 ELSE 0 END      + CASE WHEN NVL(iscl.PICKUP_LEAD_TIME,-1) != NVL(isc.PICKUP_LEAD_TIME,-1)              THEN 1 ELSE 0 END      + CASE WHEN NVL(iscl.ORIGIN_COUNTRY_ID,'X') != NVL(isc.ORIGIN_COUNTRY_ID,'X')              THEN 1 ELSE 0 END     ) DESC,     CASE         WHEN NVL(iscl.UNIT_COST,-1) != NVL(isc.UNIT_COST,-1)              AND NVL(iscl.PICKUP_LEAD_TIME,-1) != NVL(isc.PICKUP_LEAD_TIME,-1)         THEN 'COST AND LEAD TIME - HIGH IMPACT'         WHEN NVL(iscl.UNIT_COST,-1) != NVL(isc.UNIT_COST,-1)         THEN 'COST ONLY - FINANCIAL IMPACT'         ELSE 'OTHER'     END,     d.DEPT_NAME,     im.ITEM_DESC,     CASE il.LOC_TYPE WHEN 'S' THEN st.STORE_NAME WHEN 'W' THEN wh.WH_NAME END